(() => {
  document.documentElement.classList.add('tauri');
  const ta = () => document.querySelector('.composer textarea.composer-input');
  window.__cm = () => {
    const t = ta(); if (!t) return null;
    const h = document.querySelector('.composer .composer-hint');
    const cs = getComputedStyle(t), tr = t.getBoundingClientRect();
    const hr = h && h.getBoundingClientRect();
    return { cliW: t.clientWidth, scrW: t.scrollWidth, offH: t.offsetHeight, cliH: t.clientHeight,
      scrH: t.scrollHeight, ox: cs.overflowX, oy: cs.overflowY, maxH: parseFloat(cs.maxHeight),
      ph: t.hasAttribute('placeholder'), aria: t.getAttribute('aria-label'), title: t.title,
      hint: h && { shown: getComputedStyle(h).display !== 'none' && hr.height > 0, text: h.textContent,
        aria: h.getAttribute('aria-hidden'), top: hr.top - tr.top, bottom: tr.bottom - hr.bottom,
        lineH: hr.height } };
  };
  window.__type = s => { const t = ta(); t.focus(); t.value = s;
    t.dispatchEvent(new Event('input', { bubbles: true })); return s.length; };
  // + 1: a box of a fractional width (863.3 px) reads scrollWidth rounded
  // up and clientWidth down; the bug this guards against is 25% wider.
  window.__empty = () => { const m = __cm(); return !!m && !m.ph && m.scrW <= m.cliW + 1
    && m.cliH === m.offH && m.offH < 34 && m.oy === 'hidden' && m.ox === 'hidden'
    && m.hint.shown && m.hint.top >= -0.5 && m.hint.bottom >= -0.5 && m.hint.text.length > 0; };
  return 'helpers';
})()

